/* Types */
/**  What a rule does when it matches. */
export type ActionSpec = 
/**  Colours the match where it shows. */
{ kind: "highlight"; style: StyleSpec } | 
/**
 *  Tells the user: in the app, and from the system while the window is
 *  in the back.
 */
{ kind: "notify" } | 
/**  Keeps the line, for the user to read and copy. */
{ kind: "capture" } | 
/**  Types `text`, then Enter if `enter`, as the user would. */
{ kind: "send"; text: string; enter: boolean };

/**  A recording in progress, and the pane's session. */
export type ActiveRecording = {
	session: SessionHandle,
	recording: RecordingView,
};

/**  What an explanation would send, for the user to read before sending. */
export type AiPreviewView = {
	preview: number,
	text: string,
};

/**  A model's answer, as plain text. */
export type AiReplyView = {
	text: string,
	/**  One line the view may put on the prompt line without Enter. */
	command: string | null,
	/**
	 *  The prod guard's reasons to look twice at `command`, with the
	 *  built-in rules on for every host.
	 */
	findings: GuardFinding[],
};

export type AiSettingsSpec = {
	enabled: boolean,
	/**  Empty for no server. */
	baseUrl: string,
	model: string,
	localOutput: boolean,
};

